/**
 * The raw statements of a Prisma client, restated structurally: the client of the unit of work of
 * `@ddd-ts-kit/prisma` fits, inside a transaction or not. The audit package depends on no client
 * generated by Prisma.
 */
export interface PrismaAuditClient {
  $queryRawUnsafe(query: string, ...values: unknown[]): Promise<unknown>;
  $executeRawUnsafe(query: string, ...values: unknown[]): Promise<number>;
}
